import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { OrderService } from '../../services/order.service';
import { Order } from '../../models/order';

@Component({
  selector: 'app-my-orders',
  templateUrl: './my-orders.component.html',
  styleUrls: ['./my-orders.component.css']
})
export class MyOrdersComponent implements OnInit {
  orders: Order[] = [];
  loading = false;
  error: string | null = null;

  constructor(private orderService: OrderService, private router: Router) {}

  ngOnInit(): void {
    this.loadOrders();
  }

  loadOrders(): void {
    this.loading = true;
    this.error = null;
    this.orderService.getMyOrders().then((data: Order[] | undefined) => {
      this.orders = data || [];
    }).catch(err => {
      this.error = err?.error?.error || 'Failed to load orders';
    }).finally(() => {
      this.loading = false;
    });
  }

  goBack(): void {
    this.router.navigate(['/packages']);
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="bg-white shadow-sm">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
      <div class="flex items-center justify-between">
        <a (click)="goBack()" class="btn-secondary">
          <svg class="w-5 h-5 inline-block mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
          Back to Packages
        </a>
        <h1 class="text-2xl font-bold text-gray-900">My Orders</h1>
      </div>
    </div>
  </header>

  <main class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
    <div *ngIf="loading" class="text-center py-12">
      <div class="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      <p class="mt-4 text-gray-600">Loading orders...</p>
    </div>

    <div *ngIf="!loading && error" class="text-center py-12">
      <div class="text-red-500 mb-4">
        <svg class="w-12 h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-red-600">{{ error }}</p>
      <button (click)="loadOrders()" class="mt-4 bg-primary text-white px-4 py-2 rounded hover:bg-primary-dark transition-colors">
        Retry
      </button>
    </div>

    <div *ngIf="!loading && !error && orders.length === 0" class="text-center py-12">
      <svg class="w-16 h-16 mx-auto text-gray-400 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
      </svg>
      <p class="text-gray-600">No orders yet</p>
      <p class="text-gray-500 text-sm mt-2">Place your first order from the software packages page.</p>
    </div>

    <div *ngIf="!loading && !error && orders.length > 0" class="space-y-6">
      <div class="bg-white rounded-2xl shadow-lg overflow-hidden">
        <table class="w-full text-left">
          <thead>
            <tr class="bg-gray-50 border-b border-gray-200">
              <th class="px-6 py-3 text-sm font-medium text-gray-700">Package</th>
              <th class="px-6 py-3 text-sm font-medium text-gray-700">Quantity</th>
              <th class="px-6 py-3 text-sm font-medium text-gray-700">Total</th>
              <th class="px-6 py-3 text-sm font-medium text-gray-700">Status</th>
              <th class="px-6 py-3 text-sm font-medium text-gray-700">Date</th>
            </tr>
          </thead>
          <tbody class="divide-y divide-gray-200">
            <tr *ngFor="let order of orders" class="hover:bg-gray-50 transition-colors">
              <td class="px-6 py-4">
                <div class="flex items-center">
                  <img [src]="order.thumbnail || 'https://via.placeholder.com/40'" [alt]="order.title"
                    class="w-12 h-12 object-cover rounded-lg mr-4" />
                  <div>
                    <div class="font-medium text-gray-900">{{ order.title }}</div>
                  </div>
                </div>
              </td>
              <td class="px-6 py-4 text-sm text-gray-700">{{ order.quantity }}</td>
              <td class="px-6 py-4 text-sm text-gray-700 font-medium">{{ order.totalPrice | currency:'USD' }}</td>
              <td class="px-6 py-4">
                <span class="px-2 py-1 rounded-full text-xs font-medium"
                  [ngClass]="order.status === 'PENDING' ? 'bg-yellow-100 text-yellow-700' : 'bg-green-100 text-green-700'">
                  {{ order.status }}
                </span>
              </td>
              <td class="px-6 py-4 text-sm text-gray-600">{{ order.createdAt | date:'mediumDate' }}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </main>
</div>
